import { beforeEach, expect, it, vi } from "vitest";

const mocks = vi.hoisted(() => ({
  owners: vi.fn(),
  lock: vi.fn(),
  policy: vi.fn(),
}));
vi.mock("@/lib/db", () => ({ db: { user: { findMany: mocks.owners } } }));
vi.mock("@/lib/usage-ledger", () => ({ withUsageTransaction: mocks.lock }));
vi.mock("@/lib/campaign-policy", () => ({
  applyFreeCampaignPolicy: mocks.policy,
}));
import { sweepSubscriptionLifecycle } from "@/lib/subscription-maintenance";

beforeEach(() => {
  vi.resetAllMocks();
  mocks.lock.mockImplementation(async (_db, userId, work) => work({ userId }));
});

it("paginates queued owners and applies policy under each owner lock", async () => {
  const owners = Array.from({ length: 50 }, (_, i) => ({
    id: String(i).padStart(3, "0"),
  }));
  mocks.owners
    .mockResolvedValueOnce(owners)
    .mockResolvedValueOnce([{ id: "050" }]);
  await sweepSubscriptionLifecycle();
  expect(mocks.policy).toHaveBeenCalledTimes(51);
  expect(mocks.owners).toHaveBeenLastCalledWith(
    expect.objectContaining({
      where: expect.objectContaining({
        id: { gt: "049" },
        deletionRequestedAt: null,
      }),
    }),
  );
  expect(mocks.policy).toHaveBeenLastCalledWith({ userId: "050" });
});

it("continues after an owner failure and fails the command for monitoring", async () => {
  mocks.owners.mockResolvedValueOnce([{ id: "failed" }, { id: "healthy" }]);
  mocks.policy.mockRejectedValueOnce(
    new Error("database temporarily unavailable"),
  );
  await expect(sweepSubscriptionLifecycle()).rejects.toThrow(
    "SUBSCRIPTION_LIFECYCLE_INCOMPLETE",
  );
  expect(mocks.policy).toHaveBeenLastCalledWith({ userId: "healthy" });
});
